class HumanClient {
  ctx:any; snapshot:any={state:null,error:'',transportError:'',busy:false,notice:'',formVersion:0};listeners=new Set<()=>void>();timer:any;inflight:any;closed=false;generation=0;im:any=null;
  constructor(ctx:any){this.ctx=ctx;}
  getSnapshot=()=>this.snapshot;
  subscribe=(listener:()=>void)=>{this.listeners.add(listener);if(this.listeners.size===1){void this.refresh();this.timer=setInterval(()=>void this.refresh(),4000);}return ()=>{this.listeners.delete(listener);if(!this.listeners.size)clearInterval(this.timer);};};
  publish(p:any){if(this.closed)return;this.snapshot={...this.snapshot,...p};for(const l of this.listeners)l();}
  async rpc(method:string,payload:any){const result=await this.ctx.connection.rpc.call('/api','become-human-native',{method,payload},AbortSignal.timeout(60000));if(!result.ok)throw new Error(result.error?.code??'NATIVE_REQUEST_FAILED');return result.value;}
  async refresh(){if(this.inflight||this.closed)return this.inflight;const generation=this.generation;this.inflight=this.rpc('read',{kind:'state'}).then(state=>{if(generation===this.generation)this.publish({state,transportError:''});}).catch(e=>{if(generation===this.generation)this.publish({transportError:messages[e.message]??e.message});}).finally(()=>{this.inflight=null;});return this.inflight;}
  async control(body:any){if((this.snapshot.transportError||!this.snapshot.state?.management)&&!['runtime-restart','runtime-stop','setup-refresh','setup-complete','setup-reset'].includes(body.op))throw new Error('WORKER_UNAVAILABLE');this.generation++;const sid=this.snapshot.state?.sessionId,value=await this.rpc('control',{sessionId:sid,...body});const state=value?.state??value;if(state?.sessionId||state?.setup||state?.status==='unavailable')this.publish({state,formVersion:this.snapshot.formVersion+(['profile-rollback','execution-save','data-save','autonomy-configure'].includes(body.op)?1:0)});return value;}
  read(body:any){return this.rpc('read',{sessionId:this.snapshot.state?.sessionId,...body});}
  run=async(action:()=>Promise<any>,notice='已完成')=>{if(this.snapshot.busy)return;this.publish({busy:true,error:'',notice:''});try{await action();this.publish({notice});}catch(e:any){this.publish({error:messages[e.message]??e.message});}finally{this.publish({busy:false});await this.refresh();}};
  dispose(){this.closed=true;clearInterval(this.timer);this.listeners.clear();}
}
function Icon({size=18,log=false}:any){return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" aria-hidden="true">{log?<><path d="M7 4h13v17H7zM3 8h8M3 13h8M3 18h8M14 9h3M14 14h3"/></>:<><circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2M18 3l2 2 3-3"/></>}</svg>;}
function Button({children,onClick,primary=false,danger=false,disabled=false,...rest}:any){return <button type="button" className={'hn-button'+(primary?' hn-primary':'')+(danger?' hn-danger':'')} disabled={disabled} onClick={onClick} {...rest}>{children}</button>;}
function Field({label,children,wide=false,hint}:any){return <label className={'hn-field'+(wide?' hn-wide':'')}><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
function Input({value,onChange,type='text',...props}:any){return <input className="hn-input" type={type} value={value??''} onChange={e=>onChange(type==='number'?Number(e.target.value):e.target.value)} {...props}/>;}
function Text({value,onChange,rows=3,...props}:any){return <textarea className="hn-input" value={value??''} onChange={e=>onChange(e.target.value)} rows={rows} {...props}/>;}
function Select({value,onChange,options,...props}:any){return <select className="hn-input" value={value} onChange={e=>onChange(e.target.value)} {...props}>{options.map((o:any)=>{const [v,label]=Array.isArray(o)?o:[o,o];return <option key={v} value={v}>{label}</option>;})}</select>;}
function Check({label,value,onChange,disabled=false,...props}:any){return <label className="hn-check"><input type="checkbox" checked={!!value} disabled={disabled} onChange={e=>onChange(e.target.checked)} {...props}/>{label}</label>;}
function Band({children}:any){return <div className="hn-band">{children}</div>;}
function Empty({children='暂无记录'}:any){return <div className="hn-empty">{children}</div>;}
function Save({api,s,busy,revision,action,label,dirty}:any){
 const context=useSectionContext(),draft=useDraftNavigation(),stale=revision!==undefined&&revision!==s.management.revision,changed=dirty??draft?.dirty,otherDraft=!changed&&draft?.dirty;
 return <div className="hn-save"><div><strong>{changed?'有未保存的修改':otherDraft?'高级区域还有未保存的修改':'设置已保存'}</strong><p>{otherDraft?'展开对应区域，使用该区域的保存按钮。':stale?'其他页面已更新配置，请重新打开后核对。':s.desired==='running'?'运行中保存会先暂停；保存后由你恢复。':'准备好后可在右上角恢复运行。'}</p></div><div className="hn-row">{changed&&<Button disabled={busy} onClick={context.reset}>放弃修改</Button>}<Button primary disabled={busy||stale||!changed} onClick={()=>api.run(async()=>{await pauseForConfiguration(api);await action();},'设置已保存，当前保持暂停')}>{s.desired==='running'?'暂停并保存':label??'保存设置'}</Button></div></div>;
}

function useRead(api:any,input:any,nonce=0){const [result,setResult]=useState<any>({loading:true,data:null,error:''}),key=JSON.stringify([api.snapshot.state?.sessionId,input]);useEffect(()=>{let live=true;setResult({loading:true,data:null,error:''});api.read(input).then((data:any)=>{if(live)setResult({loading:false,data,error:''});}).catch((e:any)=>{if(live)setResult({loading:false,data:null,error:messages[e.message]??e.message});});return ()=>{live=false;};},[api,key,nonce]);return result;}
function ReadState({result,children}:any){return result.loading?<Empty>正在读取…</Empty>:result.error?<Band>{result.error}</Band>:children(result.data);}
function Detail({title,onClose,children}:any){const ref=useRef<HTMLElement>(null),close=useRef(onClose);close.current=onClose;useEffect(()=>{const previous=document.activeElement as HTMLElement;ref.current?.querySelector<HTMLElement>('button')?.focus();return ()=>{previous?.isConnected&&previous.focus();};},[]);return <div className="hn-modal" role="presentation"><section ref={ref} onKeyDown={e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close.current();}if(e.key==='Tab'){const list=[...(ref.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled),a[href]')??[])].filter(el=>el.offsetParent!==null),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}} role="dialog" aria-modal="true" aria-label={title} className="hn-dialog"><header><h3>{title}</h3><Button onClick={onClose} autoFocus>关闭</Button></header>{children}</section></div>;}
function JsonDetails({value,label='查看详情'}:any){return <details><summary>{label}</summary><pre>{json(value)}</pre></details>;}
function download(value:any,name:string){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([json(value)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function Chat(props:any){return <NativeChat {...props} ui={nativeUi}/>;}


function TaskDetail(props:any){return <TaskExecutionDetail {...props} ui={{Detail,ReadState,useRead,Button,Band,JsonDetails,errorText:(value:string)=>messages[value]??value}}/>;}

function Persona({api,s,busy,onSection}:any){
 const [p,setP]=useState(s.management.profile),set=(key:string,value:any)=>setP((previous:any)=>({...previous,[key]:value}));
 const dirty=JSON.stringify(p)!==JSON.stringify(s.management.profile),rev=useConfigRevision(s.management.revision,dirty,s.management.profile);useDraftGuard(dirty);
 return <><QuickPresetPicker kind="persona" value={p} dirty={dirty} onApply={(config:any)=>setP((previous:any)=>({...previous,...config}))} ui={nativeUi}/>
  <section className="hn-form-section"><div className="hn-fields"><Field label="人物名字"><Input value={p.name} maxLength={64} placeholder="人物名字" onChange={(value:any)=>set('name',value)}/></Field><Field label="与我的关系"><Input value={p.role} maxLength={160} placeholder="例如：日常伙伴、学习搭档" onChange={(value:any)=>set('role',value)}/></Field><Field label="人格与相处方式" wide hint="描述性格、兴趣，以及你希望怎样相处。"><Text value={p.corePrompt} rows={5} maxLength={512} onChange={(value:any)=>set('corePrompt',value)}/></Field></div></section>
  <OptionalSection title="更多人物信息"><div className="hn-fields"><Field label="角色的兴趣" wide><Text value={p.interests} maxLength={500} onChange={(value:any)=>set('interests',value)}/></Field><Field label="长期方向与职责" wide><Text value={p.goals} maxLength={800} onChange={(value:any)=>set('goals',value)}/></Field><Field label="希望怎样称呼你"><Input value={p.ownerName} maxLength={80} onChange={(value:any)=>set('ownerName',value)}/></Field><Field label="所在城市"><Input value={p.ownerCity} maxLength={100} onChange={(value:any)=>set('ownerCity',value)}/></Field><Field label="你的作息与交流偏好" wide><Text value={p.ownerPreferences} maxLength={800} onChange={(value:any)=>set('ownerPreferences',value)}/></Field></div></OptionalSection>
  <OptionalSection title="关系与成长"><RelationshipSettings {...{api,s,busy}} ui={nativeUi} mode="settings"/><PersonaDevelopment {...{api,s,busy}} ui={nativeUi} mode="settings"/><p className="hn-help">当前变化、选择与依据在资料中查看。</p><Button onClick={()=>onSection('growth')}>查看人物成长</Button></OptionalSection>
  <Save {...{api,s,busy,dirty,revision:rev}} action={async()=>{const result=await api.control({op:'profile-save',profile:p,expectedRevision:rev});setP((result.state??result).management.profile);}}/>
 </>;
}

function ProfileHistory({api,s,busy}:any){const [open,setOpen]=useState(false);return <><Button onClick={()=>setOpen(true)}>查看核心人格历史</Button>{open&&<ProfileHistoryDialog {...{api,s,busy}} onClose={()=>setOpen(false)}/>}</>;}
function ProfileHistoryDialog({api,s,busy,onClose}:any){const r=useRead(api,{kind:'profile-history'}),draft=useDraftNavigation();return <Detail title="核心人格与档案历史 · 最近 50 次" onClose={onClose}>{draft?.dirty&&<Band>请先保存或放弃当前表单的修改，再恢复历史人格，避免未保存的关系设置丢失。</Band>}<ReadState result={r}>{(rows:any[])=>rows.length?rows.slice().reverse().map(row=><div className="hn-line" key={row.version}><div><strong>配置修订 {row.version} · {time(row.time)}</strong><JsonDetails value={row.profile}/></div><Button disabled={busy||s.desired!=='paused'||draft?.dirty} onClick={()=>api.run(async()=>{await api.control({op:'profile-rollback',version:row.version,expectedRevision:s.management.revision});onClose();},'核心人格已恢复为新版本')}>恢复此版本</Button></div>):<Empty>首次修订后开始保留历史</Empty>}</ReadState></Detail>;}
function Models({api,s,busy}:any){
  const formValue=(state:any)=>{const x=structuredClone(state.management.execution);x.conversation={enabled:true,quietMs:4000,maxWaitMs:15000,replyBubbles:true,replyGapMs:900,...x.conversation};for(const lane of ['foreground','selection','executor'])x.routes[lane]??={provider:state.provider,model:state.model};return x;};
  const [e,setE]=useState(()=>formValue(s)),routes=s.management.allowedRoutes,dirty=JSON.stringify(e)!==JSON.stringify(formValue(s));
  const capabilities=s.management.modelCapabilities??[],effortLabels:any={'':'供应商默认',off:'关闭推理',low:'低',medium:'中',high:'高',max:'最高'};
  const selectedRoutes=['foreground','selection','executor'].map(lane=>e.routes[lane]),supported=(route:any)=>{const cap=capabilities.find((item:any)=>item.provider===route.provider&&item.model===route.model);if(cap?.adapter!=='deepseek-native')return ['low','medium','high'];const native=['off','low','high','max'];return Array.isArray(cap.reasoningEfforts)?native.filter(value=>cap.reasoningEfforts.includes(value)):native;};
  const sharedEfforts=['off','low','medium','high','max'].filter(value=>selectedRoutes.every(route=>supported(route).includes(value))),effortSupported=e.reasoningEffort===''||sharedEfforts.includes(e.reasoningEffort),unsupportedRoutes=effortSupported?[]:selectedRoutes.filter(route=>!supported(route).includes(e.reasoningEffort));
  const effortOptions=[['','供应商默认'],...sharedEfforts.map(value=>[value,effortLabels[value]]),...(!effortSupported?[[e.reasoningEffort,`${effortLabels[e.reasoningEffort]??e.reasoningEffort} · 当前模型不支持`]]:[])];
  const patch=(k:string,v:any)=>setE((x:any)=>({...x,[k]:v})),conversation=(k:string,v:any)=>setE((x:any)=>({...x,conversation:{...x.conversation,[k]:v}})),context=(k:string,v:any)=>setE((x:any)=>({...x,context:{...x.context,[k]:v}}));
  const rev=useConfigRevision(s.management.revision,dirty,formValue(s));
  useDraftGuard(dirty);
  const [separate,setSeparate]=useState(()=>!selectedRoutes.every(route=>json(route)===json(e.routes.foreground)));
  const routeOptions=routes.map((route:any)=>[json(route),route.provider+' / '+route.model]);
  return <>
    {!effortSupported&&<Band>当前思考强度与所选模型不兼容，请在高级模型设置中选择共同支持的值。</Band>}
    <section className="hn-form-section"><Field label="默认模型" hint={separate?'当前按工作类型分别配置，详见高级模型设置。':'用于聊天、选择方向和执行任务。'}><Select aria-label="默认模型" value={json(e.routes.foreground)} options={routeOptions} onChange={(value:any)=>{const route=JSON.parse(value);setE((previous:any)=>({...previous,routes:separate?{...previous.routes,foreground:route}:Object.fromEntries(['foreground','selection','executor'].map(lane=>[lane,route]))}));}}/></Field><p className="hn-help">模型与凭据来自 DSH；Human 不另设单次输出或上下文预算。</p></section>
    <SettingRow title="连续消息合并" description="等你短暂补充，再合起来回应。"><Check label="" aria-label="连续消息合并" value={e.conversation.enabled} onChange={(value:boolean)=>conversation('enabled',value)}/></SettingRow>
    <SettingRow title="分条回复" description="适合的日常回复分成少量气泡。"><Check label="" aria-label="分条回复" value={e.conversation.replyBubbles} onChange={(value:boolean)=>conversation('replyBubbles',value)}/></SettingRow>
    <OptionalSection title="高级模型设置" defaultOpen={separate||!effortSupported}><Check label="分别为不同工作选择模型" value={separate} onChange={(value:boolean)=>{setSeparate(value);if(!value)setE((previous:any)=>({...previous,routes:Object.fromEntries(['foreground','selection','executor'].map(lane=>[lane,previous.routes.foreground]))}));}}/>{separate&&<div className="hn-fields">{[['foreground','聊天'],['selection','选择方向'],['executor','执行任务']].map(([lane,label])=><Field key={lane} label={label}><Select value={json(e.routes[lane])} options={routeOptions} onChange={(value:any)=>setE((previous:any)=>({...previous,routes:{...previous.routes,[lane]:JSON.parse(value)}}))}/></Field>)}</div>}<Field label="思考强度" hint="仅列出三个模型共同支持的档位。"><Select value={e.reasoningEffort} options={effortOptions} onChange={(value:any)=>patch('reasoningEffort',value)}/></Field></OptionalSection>
    <OptionalSection title="消息节奏与历史检索"><div className="hn-fields"><Field label="补充消息等待 · 秒"><Input type="number" min={0.5} max={10} step={0.5} value={e.conversation.quietMs/1000} onChange={(value:any)=>conversation('quietMs',Math.round(value*1000))}/></Field><Field label="最多合并等待 · 秒"><Input type="number" min={2} max={30} value={e.conversation.maxWaitMs/1000} onChange={(value:any)=>conversation('maxWaitMs',Math.round(value*1000))}/></Field><Field label="手机气泡间隔 · 秒"><Input type="number" min={0.3} max={3} step={0.1} value={e.conversation.replyGapMs/1000} onChange={(value:any)=>conversation('replyGapMs',Math.round(value*1000))}/></Field>{[['memoryLimit','记忆候选 · 条',1,100],['historyLimit','近期完整对话 · 轮',1,40],['learningLimit','学习笔记候选 · 条',0,10]].map(([key,label,min,max]:any)=><Field key={key} label={label}><Input type="number" min={min} max={max} value={e.context[key]} onChange={(value:any)=>context(key,value)}/></Field>)}</div><p className="hn-help">较早的问答按需整理为摘要。实际装入内容在日志的运行诊断中查看。</p></OptionalSection>
    <Save {...{api,s,dirty,revision:rev}} busy={busy||!effortSupported} action={()=>api.control({op:'execution-save',execution:e,expectedRevision:rev})}/>
  </>;
}

function Autonomy({api,s,busy,onSection}:any){
 const [v,setV]=useState(s.autonomy.settings),[budgetOpen,setBudgetOpen]=useState(false),dirty=JSON.stringify(v)!==JSON.stringify(s.autonomy.settings);
 const patch=(key:string,value:any)=>setV((previous:any)=>({...previous,[key]:value})),rev=useConfigRevision(s.management.revision,dirty,s.autonomy.settings);useDraftGuard(dirty);
 const hours=Array.from({length:24},(_,hour)=>[hour,String(hour).padStart(2,'0')+':00']);
 return <>
  <SettingRow title="自主运行" description="有合适的事情时主动安排，也可以等待。"><Check label="" aria-label="自主运行" value={v.enabled} onChange={(value:boolean)=>patch('enabled',value)}/></SettingRow>
  <SettingRow title="主动联系我" description="分享值得聊的发现，或关心你的近况。"><Check label="" aria-label="主动联系我" value={v.proactiveEnabled} onChange={(value:boolean)=>patch('proactiveEnabled',value)}/></SettingRow>
  <SettingRow title="自主学习" description="按当前人物与需要获取公开资料。"><Check label="" aria-label="自主学习" value={v.learningEnabled} onChange={(value:boolean)=>patch('learningEnabled',value)}/></SettingRow>
  <section className="hn-form-section"><div className="hn-row hn-between"><h3>自主额度</h3><Check label="启用预算" value={v.quotaEnabled} onChange={(value:boolean)=>patch('quotaEnabled',value)}/></div>{v.quotaEnabled?<QuickPresetPicker kind="autonomy-budget" value={v} dirty={dirty} onCustom={()=>setBudgetOpen(true)} onApply={(config:any)=>setV((previous:any)=>({...previous,...config}))} ui={nativeUi}/>:<p className="hn-help">当前不按本地累计用量拦截，仍记录实际消耗。</p>}<p className="hn-help">预算只管理自主活动，你主动发起的聊天不占自主额度。</p></section>
  <section className="hn-form-section"><div className="hn-fields"><Field label="检查间隔 · 分钟"><Input type="number" min={1/6} max={60} step="any" value={v.wakeIntervalMs/60000} onChange={(value:any)=>patch('wakeIntervalMs',Math.round(value*60000))}/></Field><div className="hn-field"><span>安静时段</span><div className="hn-time-range"><Select aria-label="安静时段开始" value={v.quietStart} options={hours} onChange={(value:any)=>patch('quietStart',Number(value))}/><span>—</span><Select aria-label="安静时段结束" value={v.quietEnd} options={hours} onChange={(value:any)=>patch('quietEnd',Number(value))}/></div></div></div><p className="hn-help">{v.quietStart===v.quietEnd?'未设置安静时段。':'安静时段内减少主动打扰，定时提醒按原规则执行。'}日常时区为 UTC{v.timeZoneOffsetMinutes<0?'−':'+'}{Math.abs(v.timeZoneOffsetMinutes/60)}。</p></section>
  <details className="hn-advanced hn-optional" open={budgetOpen} onToggle={event=>setBudgetOpen(event.currentTarget.open)}><summary>详细额度与执行时限</summary>{budgetOpen&&<div className="hn-optional-body"><div className="hn-fields">{[['token','token 用量',1024,20000000],['request','请求次数',1,10000],['round','自主轮次',1,10000]].map(([key,label,min,max]:any)=><div className="hn-field" key={key}><Check label={'限制'+label} disabled={!v.quotaEnabled} value={v[key+'QuotaEnabled']} onChange={(value:boolean)=>patch(key+'QuotaEnabled',value)}/><Input aria-label={label+'上限'} type="number" min={min} max={max} disabled={!v.quotaEnabled||!v[key+'QuotaEnabled']} value={v[key+'Limit']} onChange={(value:any)=>patch(key+'Limit',value)}/></div>)}<Field label="额度统计周期"><Select value={v.budgetWindow} options={[["local-day","本地自然日"],["utc-day","UTC 自然日"],["rolling-day","滚动24小时"]]} onChange={(value:any)=>patch('budgetWindow',value)}/></Field><Field label="每轮累计执行 · 分钟"><Input type="number" min={1/60} max={60} step="any" value={v.roundTimeoutMs/60000} onChange={(value:any)=>patch('roundTimeoutMs',Math.round(value*60000))}/></Field></div><p className="hn-help">同一轮的选题与执行合计，聊天抢占期间不计时。额外额度在任务的授权与补额中处理。</p><Button onClick={()=>onSection('permission')}>查看授权与补额</Button></div>}</details>
  <OptionalSection title="更多主动联系设置"><SocialSettings value={v} patch={patch} ui={nativeUi}/><div className="hn-fields"><Field label="技术分享与关心间隔 · 分钟"><Input type="number" min={10} max={1440} value={v.contactCooldownMs/60000} onChange={(value:any)=>patch('contactCooldownMs',Math.round(value*60000))}/></Field><Field label="日常时区 · UTC 偏移分钟"><Input type="number" min={-720} max={840} step={1} value={v.timeZoneOffsetMinutes} onChange={(value:any)=>patch('timeZoneOffsetMinutes',value)}/></Field><Field label="再次检查来源 · 分钟"><Input type="number" min={10} max={1440} value={v.sourceIntervalMs/60000} onChange={(value:any)=>patch('sourceIntervalMs',Math.round(value*60000))}/></Field></div><Check label="预授权低风险学习目标自动激活" value={v.goalAutoActivateEnabled} onChange={(value:boolean)=>patch('goalAutoActivateEnabled',value)}/><p className="hn-help">只影响低风险学习建议，报告保存仍逐份批准。</p><Button onClick={()=>onSection('memory')}>配置学习来源</Button></OptionalSection>
  <Save {...{api,s,busy,dirty,revision:rev}} action={async()=>{const {quotaTransitionStart,quotaTransitionUntil,...settings}=v;const result=await api.control({op:'autonomy-configure',settings,expectedRevision:rev});setV((result.state??result).autonomy.settings);}}/>
 </>;
}

function MemoryEdit({api,row,s,busy,onClose,onSaved}:any){const [body,setBody]=useState(json(row.payload)),[expiry,setExpiry]=useState(row.valid_to?new Date(row.valid_to-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):''),[forget,setForget]=useState(false),history=useRead(api,{kind:'memory-history',memoryId:row.id});return <Detail title="记忆详情与修订" onClose={onClose}><p className="hn-mono">{row.id} · v{row.version} · {row.type} · {row.status}</p><Text aria-label="记忆内容 JSON" rows={6} value={body} onChange={setBody}/><Field label="到期时间 · 留空为长期"><Input type="datetime-local" value={expiry} onChange={setExpiry}/></Field><Band>原始来源为只读。修订写入新的主人确认版本，并使依赖旧结论的内容失效；遗忘会从活动记忆检索中移除，不会删除聊天原文。</Band><JsonDetails value={row.evidence} label="原始来源与时间"/><ReadState result={history}>{(data:any)=><JsonDetails value={data.versions} label="修订历史"/>}</ReadState><div className="hn-row"><Button primary disabled={busy||s.desired!=='paused'||row.status!=='active'||row.type==='skill'} onClick={()=>api.run(async()=>{await api.control({op:'memory-revise',memoryId:row.id,expectedVersion:row.version,payload:JSON.parse(body),validTo:expiry?new Date(expiry).getTime():null});onSaved();onClose();},'记忆已修订')}>保存修订</Button><Button danger disabled={busy||s.desired!=='paused'||row.status!=='active'} onClick={()=>setForget(true)}>遗忘此记忆</Button></div>{forget&&<Band>确认从活动检索中移除并清空本插件的修订正文？<div className="hn-row"><Button danger disabled={busy} onClick={()=>api.run(async()=>{await api.control({op:'memory-forget',memoryId:row.id,expectedVersion:row.version});onSaved();onClose();},'已遗忘')}>确认遗忘</Button><Button onClick={()=>setForget(false)}>取消</Button></div></Band>}</Detail>;}
const memoryKinds:any={identity:'身份',working:'当前工作',episode:'交流经历',fact:'已知事实',goal:'目标',skill:'学到的知识'};
function memorySummary(payload:any):string{if(typeof payload==='string')return payload;if(!payload||typeof payload!=='object')return '';const values=['text','content','summary','description','value','内容','fact','title'].map(key=>payload[key]).filter(value=>typeof value==='string');return (values.length?Array.from(new Set(values)).join(' · '):Object.values(payload).filter(value=>typeof value==='string').join(' · ')).slice(0,400)||'展开查看原记录';}
function Memories({api,s,busy}:any){const [query,setQuery]=useState(''),[type,setType]=useState(''),[offset,setOffset]=useState(0),[nonce,setNonce]=useState(0),[active,setActive]=useState(true),[row,setRow]=useState<any>(null),[add,setAdd]=useState(false),[body,setBody]=useState('{"内容":""}');const r=useRead(api,{kind:'memories',query,type,offset,limit:20,activeOnly:active},nonce);return <><div className="hn-row"><Input value={query} onChange={(v:any)=>{setQuery(v);setOffset(0);}} placeholder="查找记忆" aria-label="查找记忆"/><Select value={type} onChange={(v:any)=>{setType(v);setOffset(0);}} aria-label="记忆类型" options={[["","全部类型"],...Object.entries(memoryKinds)]}/><Check label="只看活动记忆" value={active} onChange={(v:any)=>{setActive(v);setOffset(0);}}/><Button onClick={()=>setNonce(n=>n+1)}>刷新</Button><Button onClick={()=>setAdd(true)}>添加记忆</Button></div><ReadState result={r}>{(data:any)=><><p className="hn-note">共 {data.total} 条。“学到的知识”是记忆类型，Skills 技能在设置中管理。</p>{data.items.map((m:any)=><div className="hn-line" key={m.id}><div className="hn-grow"><strong>{memoryKinds[m.type]??'记忆'}</strong><p>{({active:'当前有效',archived:'已归档',forgotten:'已遗忘'} as any)[m.status]??m.status} · {time(m.valid_from)}</p><div className="hn-preview">{memorySummary(m.payload)}</div></div><Button onClick={()=>setRow(m)}>查看 / 修订</Button></div>)}{!data.items.length&&<Empty/>}<div className="hn-row hn-between"><Button disabled={offset===0} onClick={()=>setOffset(o=>Math.max(0,o-20))}>上一页</Button><Button disabled={offset+20>=data.total} onClick={()=>setOffset(o=>o+20)}>下一页</Button></div></>}</ReadState>{row&&<MemoryEdit {...{api,s,busy,row}} onClose={()=>setRow(null)} onSaved={()=>setNonce(n=>n+1)}/>} {add&&<Detail title="添加主人确认的记忆" onClose={()=>setAdd(false)}><Field label="记忆内容 · JSON 对象"><Text rows={5} value={body} onChange={setBody}/></Field><Button primary disabled={busy||s.desired!=='paused'} onClick={()=>api.run(async()=>{await api.control({op:'memory-save',type:'fact',payload:JSON.parse(body)});setAdd(false);setNonce(n=>n+1);},'记忆已添加')}>保存为已确认事实</Button></Detail>}</>;}
function LearningIntent({value}:any){
  if(!value||value.version!==1||value.validation!=='declared-purpose-not-outcome-proof')return <section className="hn-group" aria-label="学习动机与用途"><h4>为什么学这件事</h4><p className="hn-note">这份笔记尚无学习动机与用途记录，不根据现有内容补造。</p></section>;
  const origins:Record<string,string>={'owner-goal':'主人目标','active-matter':'当前关注事项','configured-source':'已配置来源','persona-curiosity':'人物兴趣与好奇心'},motives:Record<string,string>={goal:'推进目标',question:'补齐疑问',curiosity:'探索兴趣',capability:'补充能力'};
  const text=(key:string)=>typeof value[key]==='string'&&value[key].trim()?value[key]:'尚未记录';
  return <section className="hn-group" aria-label="学习动机与用途"><h4>为什么学这件事</h4><p className="hn-note">发起背景：{origins[value.origin]??'未记录'} · {motives[value.motive]??'未记录'}</p><p><strong>为什么学：</strong>{text('gap')}</p><p><strong>对自己有什么用：</strong>{text('selfBenefit')}</p><p><strong>对你可能有什么用：</strong>{text('userBenefit')}</p><p><strong>准备怎么用：</strong>{text('expectedUse')}</p><p><strong>何时停止：</strong>{text('stopWhen')}</p><p className="hn-note">以上是 Agent 当时的计划用途，不代表收益已经实现，也不代表你对此有兴趣。</p></section>;
}
function Notes({api,s,busy}:any){const [offset,setOffset]=useState(0),[nonce,setNonce]=useState(0),[note,setNote]=useState<any>(null),[body,setBody]=useState(''),r=useRead(api,{kind:'notes',offset,limit:20},nonce);return <><Button onClick={()=>setNonce(n=>n+1)}>刷新学习笔记</Button><ReadState result={r}>{(data:any)=><><p className="hn-note">共 {data.total} 条 · 来源证据只读，人工修订保留为未重新核验的批注。</p>{data.items.map((n:any)=><div className="hn-line" key={n.id}><div className="hn-grow"><strong>{n.data?.title}</strong><p>{n.status} · {time(n.created)}</p><p>{n.data?.summary}</p>{n.data?.ownerRevision&&<Band>人工修订 / 未重新核验：{n.data.ownerRevision.summary}</Band>}<a className="hn-link" href={n.data?.source?.url} target="_blank" rel="noreferrer">打开来源 ↗</a><JsonDetails value={n.data} label="来源、摘录依据与任务"/></div><Button onClick={()=>{setNote(n);setBody(n.data.ownerRevision?.summary??'');}}>修订 / 反馈</Button></div>)}{!data.items.length&&<Empty>还没有学习笔记。</Empty>}<div className="hn-row hn-between"><Button disabled={!offset} onClick={()=>setOffset(o=>o-20)}>上一页</Button><Button disabled={offset+20>=data.total} onClick={()=>setOffset(o=>o+20)}>下一页</Button></div></>}</ReadState>{note&&<Detail title={note.data.title} onClose={()=>setNote(null)}><p>{note.data.summary}</p><LearningIntent value={note.data.learningIntent}/><Field label="人工修订或重新学习的纠正要求"><Text rows={5} value={body} onChange={setBody} maxLength={2000}/></Field><div className="hn-row"><Button disabled={busy||s.desired!=='paused'||!body.trim()||note.status!=='active'} onClick={()=>api.run(async()=>{await api.control({op:'note-revise',noteId:note.id,expectedVersion:note.data.ownerRevision?.version??0,summary:body});setNote(null);setNonce(n=>n+1);},'人工批注已保存')}>保存人工批注</Button>{[['useful','有用'],['not-now','暂时不想聊'],['correction','纠正并排队重学']].map(([value,label])=><Button key={value} disabled={busy||s.agentBusy||note.status!=='active'||value==='correction'&&!body.trim()} onClick={()=>api.run(async()=>{await api.control({op:'learning-feedback',noteId:note.id,value,comment:body.slice(0,500)});setNote(null);setNonce(n=>n+1);},'反馈已保存')}>{label}</Button>)}</div><NoteHistory api={api} id={note.id}/></Detail>}</>;}
function NoteHistory({api,id}:any){const r=useRead(api,{kind:'note-history',noteId:id});return <ReadState result={r}>{(data:any)=><JsonDetails value={data} label="人工修订历史"/>}</ReadState>;}
function LearningSettings({api,s,busy}:any){
 const [v,setV]=useState(()=>structuredClone(s.autonomy.settings)),dirty=JSON.stringify(v)!==JSON.stringify(s.autonomy.settings),rev=useConfigRevision(s.management.revision,dirty,s.autonomy.settings);useDraftGuard(dirty);
 const patch=(key:string,value:any)=>setV((previous:any)=>({...previous,[key]:value})),source=(index:number,key:string,value:string)=>setV((previous:any)=>({...previous,sources:previous.sources.map((item:any,i:number)=>i===index?{...item,[key]:value}:item)}));
 return <><h3>公开搜索与自主学习</h3><section className="hn-form-section"><h4 className="hn-section-heading">如何获取外部资料</h4><Check label="允许搜索公开资料" value={v.searchEnabled} onChange={(value:boolean)=>patch('searchEnabled',value)}/><p className="hn-help">搜索主题与公开站点不受固定来源列表限制。关闭搜索后，仍可按已配置来源进行阅读。</p><div className="hn-fields"><Field label="搜索服务"><Select value={v.searchProvider} disabled={!v.searchEnabled} options={[["bing","Bing 公开搜索"],["duckduckgo","DuckDuckGo 公开搜索"],["searxng","自有 SearXNG 服务"]]} onChange={(value:string)=>patch('searchProvider',value)}/></Field>{v.searchProvider==='searxng'&&<Field label="SearXNG 服务地址" hint="填写可访问的服务地址；无需在此表单填写密钥。"><Input value={v.searchEndpoint} maxLength={1200} disabled={!v.searchEnabled} placeholder="https://search.example.com/" onChange={(value:string)=>patch('searchEndpoint',value)}/></Field>}</div></section>
 <OptionalSection title="固定关注的来源（可选）"><section className="hn-form-section"><div className="hn-row hn-between"><div><h4 className="hn-section-heading">固定关注的来源</h4><p className="hn-help">可留空，最多8项。每个来源写清楚地址，以及希望从中了解的问题。</p></div><Button disabled={v.sources.length>=8} onClick={()=>patch('sources',[...v.sources,{url:'',title:'',topic:''}])}>添加来源</Button></div>{v.sources.length?v.sources.map((item:any,index:number)=><section className="hn-source-editor" key={index}><div className="hn-row hn-between"><strong>来源 {index+1}</strong><Button danger onClick={()=>patch('sources',v.sources.filter((_:any,i:number)=>i!==index))}>移除此来源</Button></div><div className="hn-fields"><Field label={'来源 '+(index+1)+' 名称'}><Input value={item.title} maxLength={100} placeholder="例如：官方产品更新" onChange={(value:string)=>source(index,'title',value)}/></Field><Field label={'来源 '+(index+1)+' 网页地址'}><Input value={item.url} maxLength={1200} placeholder="https://…" onChange={(value:string)=>source(index,'url',value)}/></Field><Field label={'来源 '+(index+1)+' 希望了解什么'} wide hint="写一个具体方向或问题，最多200字。"><Text value={item.topic} maxLength={200} rows={2} onChange={(value:string)=>source(index,'topic',value)}/></Field></div></section>):<Empty>尚未指定固定来源；启用公开搜索后仍可探索新内容。</Empty>}</section></OptionalSection>
 <p className="hn-help">来源地址、读取时间与证据保存在学习记录中。没有读到有效资料时不会把任务写成学习成功。</p><Save {...{api,s,busy,revision:rev}} label="保存学习设置" action={async()=>{const result=await api.control({op:'autonomy-configure',expectedRevision:rev,settings:{searchEnabled:v.searchEnabled,searchProvider:v.searchProvider,searchEndpoint:v.searchEndpoint,sources:v.sources}});setV((result.state??result).autonomy.settings);}}/></>;
}
function LocalTabs({entries,active,onSelect,label}:any){const navigation=useDraftNavigation();return <div className="hn-tabs hn-local-tabs" role="tablist" aria-label={label}>{entries.map(([id,title]:any)=><Button key={id} role="tab" aria-selected={active===id} onClick={()=>{if(active!==id)navigation.navigate(()=>onSelect(id));}}>{title}</Button>)}</div>;}
function MemorySettings(props:any){const [tab,setTab]=useState('sources');return <><LocalTabs entries={[["sources","学习来源"],["organize","记忆整理"]]} active={tab} onSelect={setTab} label="记忆与学习设置"/>{tab==='sources'?<LearningSettings {...props}/>:<MemoryLifecycle {...props} mode="settings" ui={nativeUi}/>}</>;}
function ToolSettings(props:any){const [tab,setTab]=useState(props.initialSection==='skills'?'skills':'connections');return <><LocalTabs entries={[["connections","工具连接"],["skills","Skills 技能"]]} active={tab} onSelect={setTab} label="工具与技能设置"/>{tab==='connections'?<CapabilitySettings {...props} ui={nativeUi}/>:<Skills {...props}/>}</>;}
