function PanelContent({api,useHuman,initialView='chat'}:any){
 const {state:liveState,error,transportError,busy:requestBusy,notice,formVersion}=useHuman((value:any)=>value),navigation=useDraftNavigation(),lastGood=useRef<any>(null);if(liveState?.management)lastGood.current=liveState;const s=liveState?.management?liveState:lastGood.current,disconnected=!!transportError||(!liveState?.management&&!!s),busy=requestBusy||disconnected;
 const normalize=(view:string)=>['brain','activity','events'].includes(view)?'logs':view==='board'?'tasks':view;
 const [view,setView]=useState(()=>normalize(initialView)),[activityMode,setActivityMode]=useState(initialView==='activity'?'events':'brain'),[setting,setSetting]=useState('persona'),[resource,setResource]=useState('memories'),[task,setTask]=useState(initialView==='board'?'attention':'overview');
 useEffect(()=>{setView(normalize(initialView));if(['brain','activity','events'].includes(initialView))setActivityMode(initialView==='brain'?'brain':'events');},[initialView]);
 const changeView=(next:string)=>{if(next!==view)navigation.navigate(()=>setView(next));};
 const goSection=(next:string)=>navigation.navigate(()=>{
  if(next==='statistics'){setView('statistics');return;}
  if(['context','diagnostics','runtime','delivery','events','brain'].includes(next)){setActivityMode(next==='context'||next==='diagnostics'?'runtime':next);setView('logs');return;}
  if(resourceSections.some(item=>item.id===next)){setResource(next);setView('resources');return;}
  if(taskSections.some(item=>item.id===next)){setTask(next);setView('tasks');return;}
  setSetting(settingsSections.some(item=>item.id===next)||next==='skills'?next:'persona');setView('settings');
 });
 if(liveState?.setup&&(liveState.setup.required||['welcome','creating','failed'].includes(liveState.setup.phase)))return <div className="human-native"><style>{css+noviceCss}</style><Onboarding api={api} s={liveState} busy={requestBusy} ui={nativeUi} error={error} transportError={transportError}/></div>;
 if(!s?.management){const unavailable=liveState??s,code=unavailable?.setup?.error??unavailable?.manager?.error;return <div className="human-native"><style>{css+noviceCss}</style><div className="hn-content"><h2>Human</h2><Band>{error||transportError||(code?nativeUi.errorText(code):'正在连接运行服务，请稍候…')}</Band>{unavailable?.setup?.environment?.issues?.map((issue:any)=><p key={issue.code}>{issue.message}</p>)}<Recovery api={api} s={unavailable} ui={nativeUi}/></div></div>;}
 const running=s.desired==='running',status=s.activeLane?({foreground:'正在与你交流',selection:'选择下一件事',executor:'正在完成任务',autonomous:'正在完成任务',reminder:'准备提醒',scheduled:'执行定时任务',action:'执行已批准行动',tool:'读取公开网页'} as any)[s.activeLane]??'正在处理任务':running?(s.autonomy.phase==='collecting-input'&&s.inbox?'等你补充消息':s.autonomy.paused?'聊天在线 · 自主已暂停':'在线待机'):'已暂停';
 return <div className="human-native"><style>{css+noviceCss}</style><header className="hn-header"><div className="hn-identity"><span className="hn-avatar" aria-hidden="true">H</span><div><div className="hn-identity-title"><h1>{s.management.profile.name}</h1><button type="button" className={'hn-live-state'+(running?'':' hn-paused-state')} onClick={()=>goSection('runtime')} title="查看运行状态与诊断"><i/>{status}</button></div><p>网页与手机共享同一会话</p></div></div><WorkspaceTabs active={view} onChange={changeView}/><Button disabled={busy||s.status==='unavailable'} title={running?'暂停后台任务与消息处理；新消息会保留排队':'恢复原有运行方式，不自动重试失败任务'} onClick={()=>api.run(()=>api.control(running?{op:'pause'}:{op:'start',expectedEpoch:s.cancelEpoch}),running?'已暂停全部处理，新消息会保留排队':'已恢复 Human')}>{running?'暂停全部':'恢复运行'}</Button></header>
 {(error||transportError)&&<div className="hn-notice hn-error" role="alert">{error||transportError}{!transportError&&<button onClick={()=>api.publish({error:''})} aria-label="关闭错误提示">×</button>}</div>}
 {disconnected&&<details className="hn-offline-panel" open><summary>服务连接中断，当前草稿已保留。恢复前不能提交修改。</summary><Recovery api={api} s={liveState} ui={nativeUi}/></details>}
 {notice&&<div className="hn-notice" role="status">{notice}<button onClick={()=>api.publish({notice:''})} aria-label="关闭成功提示">×</button></div>}
 {view==='chat'?<Chat {...{api,s,busy}}/>:view==='board'?<div className="hn-scroll"><CharacterBoard {...{api,s,busy}} ui={nativeUi} onSection={goSection}/></div>:view==='statistics'?<div className="hn-scroll"><UsageStatistics {...{api,s,busy}} ui={nativeUi}/></div>:view==='logs'?<div className="hn-scroll"><ActivityPage {...{api,s}} ui={nativeUi} initialMode={activityMode} renderRuntime={()=> <RuntimeDiagnostics {...{api,s,busy}} onSection={goSection}/>} renderDelivery={()=> <DeliveryLogs {...{api,s}}/>}/></div>:<Settings {...{api,s,busy,formVersion}} kind={view} active={view==='tasks'?task:view==='resources'?resource:setting} onSelect={(next:string)=>{if(next===(view==='tasks'?task:view==='resources'?resource:setting))return;navigation.navigate(()=>view==='tasks'?setTask(next):view==='resources'?setResource(next):setSetting(next));}} onSection={goSection}/>}<DraftPrompt ui={nativeUi}/></div>;
}
